  "admin-guide/guides/sso": {
    slug: "admin-guide/guides/sso",
    tab: "Enterprise Control",
    group: "Security",
    title: "Konfigurasi SSO & SAML",
    sidebarTitle: "Konfigurasi SSO & SAML",
    description: "Konfigurasikan Single Sign-On (SSO) untuk autentikasi aman dan terpusat",
    icon: "key",
    body: "## Gambaran Umum\n\nSingle Sign-On (SSO) memungkinkan pengguna login ke Anticeil menggunakan penyedia identitas perusahaan (IdP) seperti Okta, Azure AD, atau Google Workspace.\n\n<Note>\nSSO memerlukan lisensi Enterprise.\n</Note>\n\n## Protokol yang Didukung\n\n- **SAML 2.0**: Untuk Okta, Azure AD, Google Workspace, OneLogin\n- **OIDC**: Untuk penyedia OpenID Connect\n\n## Konfigurasi SAML\n\n### 1. Dapatkan Metadata Anticeil\n\nDi **Pengaturan** \u2192 **SSO**, salin:\n- SP Entity ID\n- ACS URL (Assertion Consumer Service)\n\n### 2. Konfigurasi di IdP\n\nDi Okta / Azure AD / Google Workspace:\n1. Buat aplikasi SAML baru\n2. Masukkan SP Entity ID dan ACS URL dari Anticeil\n3. Petakan atribut: email, firstName, lastName\n\n### 3. Masukkan Metadata IdP ke Anticeil\n\nMasukkan:\n- IdP Entity ID\n- SSO URL\n- Sertifikat X.509\n\n### 4. Uji Koneksi\n\nKlik **Uji Koneksi** untuk memverifikasi konfigurasi.\n\n## Provisioning Pengguna\n\nKombinasikan SSO dengan SCIM untuk provisi pengguna otomatis.",
    toc: [{"id": "gambaran-umum", "title": "Gambaran Umum", "level": 2}, {"id": "protokol-yang-didukung", "title": "Protokol yang Didukung", "level": 2}, {"id": "konfigurasi-saml", "title": "Konfigurasi SAML", "level": 2}, {"id": "1-dapatkan-metadata-anticeil", "title": "1. Dapatkan Metadata Anticeil", "level": 3}, {"id": "2-konfigurasi-di-idp", "title": "2. Konfigurasi di IdP", "level": 3}, {"id": "3-masukkan-metadata-idp-ke-anticeil", "title": "3. Masukkan Metadata IdP ke Anticeil", "level": 3}, {"id": "4-uji-koneksi", "title": "4. Uji Koneksi", "level": 3}, {"id": "provisioning-pengguna", "title": "Provisioning Pengguna", "level": 2}],
  },
  "admin-guide/security/practices": {
    slug: "admin-guide/security/practices",
    tab: "Enterprise Control",
    group: "Security",
    title: "Praktik Keamanan & Data",
    sidebarTitle: "Praktik Keamanan",
    description: "Standar enkripsi, manajemen kredensial, dan isolasi sandbox di Anticeil",
    icon: "lock",
    body: "Keamanan data adalah prioritas utama Anticeil. Panduan ini menjelaskan arsitektur keamanan kami:\n\n- **Enkripsi AES-256-GCM:** Seluruh token rahasia dan kunci autentikasi disimpan dalam database dalam format terenkripsi.\n- **Isolasi Sandbox Eksekusi:** Setiap langkah kode khusus dijalankan dalam lingkungan terisolasi untuk mencegah akses tak berizin ke sistem berkas host atau jaringan internal.\n- **Pencegahan SSRF:** Proteksi jaringan internal bawaan memblokir permintaan berbahaya ke alamat IP privat lokal.\n",
    toc: [],
  },
